<script setup lang="ts">
/**
 * A thin line that divides content (`design/components/separator.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/separator.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import styles from '@polymorph/recipes/structure/separator.module.css'

export type SeparatorOrientation = NonNullable<SeparatorProps['orientation']>

export interface SeparatorProps {
  /**
   * The divider's text, rendered as given; the caller chooses the case, as in "OR".
   */
  label?: string
  /**
   * Vertical needs a sized flex row to stretch inside.
   */
  orientation?: 'horizontal' | 'vertical'
}

defineOptions({ name: 'Separator', inheritAttrs: false })

withDefaults(defineProps<SeparatorProps>(), { orientation: 'horizontal' })
</script>

<template>
  <div
    v-if="label !== undefined"
    :class="styles.labelled"
    data-orientation="horizontal"
    data-member="separator"
  >
    <!-- rule -->
    <span :class="styles.rule" />
    <!-- label -->
    <span :class="styles.label">
      {{ label }}
    </span>
    <!-- rule -->
    <span :class="styles.rule" />
  </div>
  <div
    v-else
    :class="styles.separator"
    :data-orientation="orientation"
    aria-hidden="true"
    data-member="separator"
  />
</template>
